def listify(items: Optional[List[str]], default_value: List[str] = []) -> List[str]:
    return items if items is not None else default_value


def parse_min_should_match(num_search_terms: int, spec: str) -> int:
    if spec == "1":
        return 1
    elif spec == "2":
        return 2
    elif spec == "3":
        return 3
    elif spec == "50%":
        return int(num_search_terms / 2)
    elif spec == "75%":
        return int(num_search_terms * 3 / 4)
    elif spec == "100%":
        return num_search_terms
    else:
        raise ValueError(f"Invalid mm value: {spec}")


